(2110822, 286792, 41574, '<td valign="top">The "romance" is quite apparent here, but the unsaturated colors hurt what the picture sets out to accomplish. Also, a deeper background could have added to the shot.</td>', 'The "romance" is quite apparent here, but the unsaturated colors hurt what the picture sets out to accomplish. Also, a deeper background could have added to the shot.', '2006-02-01 13:52:28.000000', NULL, 1),
(2110825, 289384, 41574, '<td valign="top">The strongly vertical composition doesn''t really work, here; I saw the picture on my 800X600 monitor (top and bottom hidden), and it looked mich better than it did when I made the whole thing fit on the screen at once.</td>', 'The strongly vertical composition doesn''t really work, here; I saw the picture on my 800X600 monitor (top and bottom hidden), and it looked mich better than it did when I made the whole thing fit on the screen at once.', '2006-02-01 13:53:45.000000', NULL, 1),
(2110827, 287801, 41574, '<td valign="top">Hehe: animals. I like it. Good job: nice composition, good colors and lighting, fun "poses." I really like it.</td>', 'Hehe: animals. I like it. Good job: nice composition, good colors and lighting, fun "poses." I really like it.', '2006-02-01 13:54:16.000000', NULL, 1),
