(2115210, 289161, 45790, '<td valign="top">Clever idea but lighting is poor and "rope" is out of focus. Rapunsel''s motion blur is fine.</td>', 'Clever idea but lighting is poor and "rope" is out of focus. Rapunsel''s motion blur is fine.', '2006-02-02 16:05:42.000000', NULL, 1),
(2115215, 285902, 45790, '<td valign="top">Snapshot, but works well for topic. Would improve with better (less harsh) lighting, off center subject, no merge with top of woman''s head, and without the man''s arms jutting toward the camera.</td>', 'Snapshot, but works well for topic. Would improve with better (less harsh) lighting, off center subject, no merge with top of woman''s head, and without the man''s arms jutting toward the camera.', '2006-02-02 16:08:49.000000', NULL, 1),
(2115230, 288780, 45790, '<td valign="top">I don''t get the painting which monopolizes the frame. I can only guess the framed photograph is from the honeymoon? Bring the photograph forward (and into focus) and have a plain background and it would be much better.</td>', 'I don''t get the painting which monopolizes the frame. I can only guess the framed photograph is from the honeymoon? Bring the photograph forward (and into focus) and have a plain background and it would be much better.', '2006-02-02 16:12:35.000000', NULL, 1),
