(2115248, 288198, 45790, '<td valign="top">Cynical since romance is great at any age. Photographs of dead flowers are never attractive, IMHO.</td>', 'Cynical since romance is great at any age. Photographs of dead flowers are never attractive, IMHO.', '2006-02-02 16:16:25.000000', NULL, 1),
(2115267, 288073, 45790, '<td valign="top">Certainly controversial. It''s effective with the strong lighting, good exposure and focus, and the centered subject works well for being a target of sorts.</td>', 'Certainly controversial. It''s effective with the strong lighting, good exposure and focus, and the centered subject works well for being a target of sorts.', '2006-02-02 16:21:33.000000', NULL, 1),
