(2115920, 288051, 29748, '<td valign="top">OMG, These are beautiful colors.</td>', 'OMG, These are beautiful colors.', '2006-02-02 20:33:17.000000', NULL, 1),
(2115921, 287184, 29748, '<td valign="top">YES YES YES......Everything about this is picture perfect, but it appears to be slightly grainy.</td>', 'YES YES YES......Everything about this is picture perfect, but it appears to be slightly grainy.', '2006-02-02 20:34:20.000000', NULL, 1),
