(2115956, 287123, 29906, '<td valign="top">This is awesome, 10</td>', 'This is awesome, 10', '2006-02-02 20:51:07.000000', NULL, 1),
(2116196, 288633, 51509, '<td valign="top">love this shot, the space just gives it that feeling that a question really is being asked.</td>', 'love this shot, the space just gives it that feeling that a question really is being asked.', '2006-02-02 22:09:28.000000', NULL, 1),
