(2116677, 288642, 45928, '<td valign="top">This seems a little too much like a M.A.C. cosmetics advertisement... beautiful girl, beautiful shot, but the lighting could have been better and the shot a little more original.</td>', 'This seems a little too much like a M.A.C. cosmetics advertisement... beautiful girl, beautiful shot, but the lighting could have been better and the shot a little more original.', '2006-02-03 00:07:24.000000', NULL, 1),
(2116680, 288932, 10261, '<td valign="top">The challenge topic was romance, not love. I can see how this image might portray love, but romance is too much of a stretch. I think that I would have preferred to see the white balance adjusted to make the napkin white.</td>', 'The challenge topic was romance, not love. I can see how this image might portray love, but romance is too much of a stretch. I think that I would have preferred to see the white balance adjusted to make the napkin white.', '2006-02-03 00:07:57.000000', NULL, 1),
