(2116693, 288299, 45928, '<td valign="top">Most voters will probly be marked down because flowers appear to be a cliched image for romance, but this is very nicely done. Great colors, dop, and angle. In my opinion these elements make it original enough. 9.</td>', 'Most voters will probly be marked down because flowers appear to be a cliched image for romance, but this is very nicely done. Great colors, dop, and angle. In my opinion these elements make it original enough. 9.', '2006-02-03 00:10:07.000000', NULL, 1),
(2116701, 289254, 10261, '<td valign="top">The foreground is too cluttered to allow the larger rock to be a clear focal point. Even if the rock did strongly resemble a heart (either anatomically or ironically) this is still exceptionally far removed from the challenge topic of "romance".</td>', 'The foreground is too cluttered to allow the larger rock to be a clear focal point. Even if the rock did strongly resemble a heart (either anatomically or ironically) this is still exceptionally far removed from the challenge topic of "romance".', '2006-02-03 00:11:59.000000', NULL, 1),
(2116709, 287973, 45928, '<td valign="top">I wish this had of been cropped just above the one way sign... the christmas lights at the top are very distracting... would be a fantastic pic without them.</td>', 'I wish this had of been cropped just above the one way sign... the christmas lights at the top are very distracting... would be a fantastic pic without them.', '2006-02-03 00:13:36.000000', NULL, 1),
