(2120004, 288475, 41522, '<td valign="top">I really wish that this image were larger so that I could properly rank it.</td>', 'I really wish that this image were larger so that I could properly rank it.', '2006-02-03 21:00:51.000000', NULL, 1),
(2120181, 287268, 42638, '<td valign="top">Wow, wonderful capture. Interesting color, it almost blends with the water. The frame is a bit distracting though I like how the image continues out of the border.</td>', 'Wow, wonderful capture. Interesting color, it almost blends with the water. The frame is a bit distracting though I like how the image continues out of the border.', '2006-02-03 22:04:56.000000', NULL, 1),
(2120182, 287930, 42638, '<td valign="top">Very nice. Love the soft, gentle feel of this.</td>', 'Very nice. Love the soft, gentle feel of this.', '2006-02-03 22:05:28.000000', NULL, 1),
(2120188, 289090, 42638, '<td valign="top">Very nice, Looks like they''ve been together for a whle.</td>', 'Very nice, Looks like they''ve been together for a whle.', '2006-02-03 22:07:49.000000', NULL, 1),
(2120190, 287973, 51156, '<td valign="top">Great composition, lots of interesting items captured, yet they don''t detract from the main subject.  Nice job.</td>', 'Great composition, lots of interesting items captured, yet they don''t detract from the main subject.  Nice job.', '2006-02-03 22:08:46.000000', NULL, 1),
(2120191, 286094, 51156, '<td valign="top">Vibrant arresting</td>', 'Vibrant arresting', '2006-02-03 22:09:07.000000', NULL, 1),
(2120194, 287539, 42638, '<td valign="top">Aww, Very cute! If I wasn''t looking at my dog right now, I would swear that was him. This really gives off a nice innocent and playful feel with this picture. All the brown hues nicely add to the warmth. Well done!</td>', 'Aww, Very cute! If I wasn''t looking at my dog right now, I would swear that was him. This really gives off a nice innocent and playful feel with this picture. All the brown hues nicely add to the warmth. Well done!', '2006-02-03 22:09:59.000000', NULL, 1),
(2120203, 286053, 51156, '<td valign="top">It might have been more effective with just the photos and the flowers.  I find the jewelery distracting.</td>', 'It might have been more effective with just the photos and the flowers.  I find the jewelery distracting.', '2006-02-03 22:12:51.000000', NULL, 1),
(2120204, 289276, 42638, '<td valign="top">Wonderful image, love the color. I am trying to figure out what the background is, At first I thought it was sky but now I see its more flowers. Good soft feel here.</td>', 'Wonderful image, love the color. I am trying to figure out what the background is, At first I thought it was sky but now I see its more flowers. Good soft feel here.', '2006-02-03 22:12:57.000000', NULL, 1),
(2120210, 289089, 51156, '<td valign="top">LOL</td>', 'LOL', '2006-02-03 22:15:08.000000', NULL, 1),
(2120213, 286901, 51156, '<td valign="top">LOL, clever idea well done</td>', 'LOL, clever idea well done', '2006-02-03 22:16:25.000000', NULL, 1),
(2120215, 288051, 42638, '<td valign="top">Wonderful colors, Lovely interpretation. I really like the innocent silhouette. The wisps of tall grass really dull the bright spots well on the bottom. Nicely done!</td>', 'Wonderful colors, Lovely interpretation. I really like the innocent silhouette. The wisps of tall grass really dull the bright spots well on the bottom. Nicely done!', '2006-02-03 22:17:29.000000', NULL, 1),
(2120220, 288687, 42638, '<td valign="top">Beautiful picture, looks like a brocure for a tropical getaway. Good use of framing with the palm tree, give it a sense of closure with the beach as well.</td>', 'Beautiful picture, looks like a brocure for a tropical getaway. Good use of framing with the palm tree, give it a sense of closure with the beach as well.', '2006-02-03 22:19:26.000000', NULL, 1),
(2120223, 289108, 42638, '<td valign="top">Very nice, I really like how you have framed this one. Funny, it looks like he is in the middle of a giggle, made me giggle just looking.</td>', 'Very nice, I really like how you have framed this one. Funny, it looks like he is in the middle of a giggle, made me giggle just looking.', '2006-02-03 22:22:22.000000', NULL, 1),
(2120226, 289374, 42638, '<td valign="top">Wow, Beautiful! Great imagination. I suddenly find myself thinking of V-Day ideas. Excellent composition and lighting.</td>', 'Wow, Beautiful! Great imagination. I suddenly find myself thinking of V-Day ideas. Excellent composition and lighting.', '2006-02-03 22:24:12.000000', NULL, 1),
(2120229, 289230, 42638, '<td valign="top">Excellent focus. Looks like a magazine ad. Wonderful lighting. The shadows actually add to the power of this, not usually the case but I like them here. Nicely done.</td>', 'Excellent focus. Looks like a magazine ad. Wonderful lighting. The shadows actually add to the power of this, not usually the case but I like them here. Nicely done.', '2006-02-03 22:26:16.000000', NULL, 1),
(2120251, 289425, 42638, '<td valign="top">Beautiful, love the water drops and the reflection caught in the ones on the right side. Good colors and composition</td>', 'Beautiful, love the water drops and the reflection caught in the ones on the right side. Good colors and composition', '2006-02-03 22:38:38.000000', NULL, 1),
(2120253, 288456, 42638, '<td valign="top">Wonderful close-up. Love the details and color. Good use of space.</td>', 'Wonderful close-up. Love the details and color. Good use of space.', '2006-02-03 22:39:22.000000', NULL, 1),
(2120300, 287388, 35578, '<td valign="top">Being a food photographer this shot needs a lot of work.  I see where you were going with the idea but this honestly looks nothing like what any palate would want to be romanced by.</td>', 'Being a food photographer this shot needs a lot of work.  I see where you were going with the idea but this honestly looks nothing like what any palate would want to be romanced by.', '2006-02-03 22:59:18.000000', NULL, 1),
(2120303, 287044, 35578, '<td valign="top">Nice idea with the "heart" shape of the hands... but where is the wedding ring of the woman?</td>', 'Nice idea with the "heart" shape of the hands... but where is the wedding ring of the woman?', '2006-02-03 23:00:32.000000', NULL, 1),
(2120307, 287827, 35578, '<td valign="top">Artificial flowers, cheap champagne or wine is a winning combination?</td>', 'Artificial flowers, cheap champagne or wine is a winning combination?', '2006-02-03 23:01:37.000000', NULL, 1),
(2120315, 289106, 35578, '<td valign="top">How is star anise, pinecones, cheap gold ribbon and a ring suspended in some read liquid a proposal?  Don''t really see the romance here?</td>', 'How is star anise, pinecones, cheap gold ribbon and a ring suspended in some read liquid a proposal?  Don''t really see the romance here?', '2006-02-03 23:03:41.000000', NULL, 1),
