(2120725, 289089, 18157, '<td valign="top">AHHH! I love it! I hope you gave them lots of treats for this.</td>', 'AHHH! I love it! I hope you gave them lots of treats for this.', '2006-02-04 02:31:59.000000', NULL, 1),
(2120984, 289151, 18073, '<td valign="top">Nice idea and good fun too look at.  The image seems a little too bright too me with the brushes being hard to pick out against the white BG.  Good effort though, well done!   6/10</td>', 'Nice idea and good fun too look at.  The image seems a little too bright too me with the brushes being hard to pick out against the white BG.  Good effort though, well done!   6/10', '2006-02-04 08:09:31.000000', NULL, 1),
(2120987, 289276, 18073, '<td valign="top">Beautiful shot.  Love the colour and pattern of the background and the detail and clarity of the rose is spot on.  Lovely image, good job!</td>', 'Beautiful shot.  Love the colour and pattern of the background and the detail and clarity of the rose is spot on.  Lovely image, good job!', '2006-02-04 08:10:31.000000', NULL, 1),
(2121065, 288979, 29513, '<td valign="top">I like the flowers not being bunched together.  I might try to find a way to make the background contrast more with the flowers.</td>', 'I like the flowers not being bunched together.  I might try to find a way to make the background contrast more with the flowers.', '2006-02-04 09:20:13.000000', NULL, 1),
(2121082, 288716, 29513, '<td valign="top">I like your idea.  I find the candle flame distracting and the focus just a little too soft for my taste, though.</td>', 'I like your idea.  I find the candle flame distracting and the focus just a little too soft for my taste, though.', '2006-02-04 09:27:07.000000', NULL, 1),
(2121104, 289230, 29513, '<td valign="top">I like your arrangement of the rings.  I might try a more contrasting background, though.  Since the metal of the rings reflect what they are laying on, they seem to almost disappear into the white.</td>', 'I like your arrangement of the rings.  I might try a more contrasting background, though.  Since the metal of the rings reflect what they are laying on, they seem to almost disappear into the white.', '2006-02-04 09:41:35.000000', NULL, 1),
(2121110, 285822, 29513, '<td valign="top">I like this a lot.  Allowing the people to be in motion blurr really moves the subject to what they are doing a feeling.  Best I''ve seen so far.</td>', 'I like this a lot.  Allowing the people to be in motion blurr really moves the subject to what they are doing a feeling.  Best I''ve seen so far.', '2006-02-04 09:44:47.000000', NULL, 1),
