(2130790, 288596, 25678, '<td valign="top">I like the idea of this.  The flash seems a bit harsh for this.</td>', 'I like the idea of this.  The flash seems a bit harsh for this.', '2006-02-07 20:04:20.000000', NULL, 1),
(2130792, 288073, 25678, '<td valign="top">Interesting idea, but I''m not a fan of the shadow behind her</td>', 'Interesting idea, but I''m not a fan of the shadow behind her', '2006-02-07 20:04:51.000000', NULL, 1),
