(2131082, 289294, 45596, '<td valign="top">Very clever!</td>', 'Very clever!', '2006-02-07 21:28:23.000000', NULL, 1),
(2131083, 287541, 52516, '<td valign="top">Captured the moment, just wish it were clearer.</td>', 'Captured the moment, just wish it were clearer.', '2006-02-07 21:28:30.000000', NULL, 1),
